command:
if (game.system.id !== "impmal" || !game.modules.get("kyra-sheet")?.active) {
  return ui.notifications.warn("Enable Kyra's Sheet in an Imperium Maledictum world first.");
}
const selectedTokens = canvas.tokens?.controlled ?? [];
if (selectedTokens.length !== 1) {
  return ui.notifications.warn("Select exactly one character token, then run this macro.");
}
const targetActor = selectedTokens[0].actor;
if (!targetActor || targetActor.type !== "character" || !targetActor.isOwner) {
  return ui.notifications.warn("Select a character token you are allowed to edit.");
}
const tokenUpdates = {
  "bar1.attribute": "combat.wounds",
  "bar2.attribute": "warp.charge",
  displayBars: CONST.TOKEN_DISPLAY_MODES.OWNER_HOVER
};
let updatedCount = 0;
let failedCount = 0;
const applyBars = async (document, updates) => {
  try {
    await document.update(updates);
    updatedCount++;
  } catch (error) {
    failedCount++;
    console.error("Kyra's Sheet: token bar configuration failed.", error);
  }
};
if (targetActor.isToken) {
  // An unlinked token has independent actor data; configure just this token.
  await applyBars(targetActor.token, tokenUpdates);
} else {
  await applyBars(targetActor, Object.fromEntries(
    Object.entries(tokenUpdates).map(([key, value]) => [`prototypeToken.${key}`, value])
  ));
  for (const scene of game.scenes) {
    for (const placedToken of scene.tokens) {
      if (placedToken.actorId === targetActor.id && placedToken.actorLink && placedToken.isOwner) {
        await applyBars(placedToken, tokenUpdates);
      }
    }
  }
}
const resultMessage = `Configured ${updatedCount} token/prototype record(s): Wounds / Warp Charge.`;
if (failedCount) ui.notifications.warn(`${resultMessage} ${failedCount} update(s) failed; see console.`);
else ui.notifications.info(resultMessage);
